&reftitle.description;
boolflock resourcestream intoperation intwould_block&null;
Функция flock устанавливает блокировку файла на чтение или запись. Функция помогает организовать модель «читатель-писатель», которая поддерживается на большей части платформ на основе Unix и даже в Windows.
Вызов функции с флагом LOCK_UN снимает блокировку. Блокировка также снимается при вызове функции fclose или когда сборщик мусора уничтожает поток stream.
PHP поддерживает переносимый способ блокировки файлов целиком, который держится на «джентльменском соглашении» и работает, только если при доступе к файлу каждая программа действует в рамках единой согласованной модели блокировок — вызывает функцию flock и учитывает чужие блокировки. По умолчанию функция приостанавливает выполнение скрипта и ждёт, пока не получит запрошенную блокировку файла, если только поведение блокировки не изменили флагом LOCK_NB.

  &reftitle.examples;



    Пример блокировки файла функцией flock


<?php

$fp = fopen("/tmp/lock.txt", "r+");

if (flock($fp, LOCK_EX)) { // Ставим эксклюзивную блокировку
    ftruncate($fp, 0); // Усекаем файл
    rewind($fp);
    fwrite($fp, "Пишем что-нибудь сюда\n");
    fflush($fp);         // Очищаем вывод перед снятием блокировки
    flock($fp, LOCK_UN); // Снимаем блокировку
} else {
    echo "Не получилось заблокировать файл!";
}

fclose($fp);







    Пример вызова функции flock с флагом LOCK_NB


<?php

$fp = fopen('/tmp/lock.txt', 'r+');

/* Включаем опцию LOCK_NB в операцию LOCK_EX */
if (!flock($fp, LOCK_EX | LOCK_NB)) {
    echo 'Не получилось заблокировать файл';
    exit(-1);
}

/* ... */

fclose($fp);
